selector .elementor-shape-divider::before { /* Adjust selector as needed */
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: inherit; /* Inherit divider color */
    /* Add your glow */
    box-shadow: 0 0 20px 5px rgba(255, 0, 255, 0.7), /* Pink glow */
                0 0 40px 10px rgba(0, 255, 255, 0.5); /* Cyan glow */
    z-index: -1; /* Place behind content */
    border-radius: inherit;
}
/* Optional: Hover Effect */
selector:hover .elementor-shape-divider::before {
    box-shadow: 0 0 30px 10px rgba(255, 255, 0, 0.9), /* Yellow glow on hover */
                0 0 60px 15px rgba(0, 255, 0, 0.7);
}

